/* Practitioner's Training: online edition. Content only; app.js draws it.
   SOURCE: Onesimus workshop "Supporting Children and Families Affected by Key Attachment Figure Offending"
   (lesson plan and slides 180314, handouts 01–09), and the 2018 Practitioner's Guide (Australia).
   "orig" = the workshop's own wording, word for word, shown in a fold-out.
   "flag" = a review note, shown in Reviewer view. */
window.PT = { modules: [] };
PT.FG = "https://normreed-tas.github.io/field-guide/";
PT.passMark = 7;

/* ---------- the five workshop case studies, in Tasmanian terms ---------- */
PT.cases = [
  { id: "c1", name: "Claire and Sarah", line: "A three-year-old told that Dad is working away",
    text: "Claire's ex-partner is serving five years. Their daughter Sarah was three when he was arrested. Before that, Sarah spent a lot of time with her father, who shared her care. No services were involved with the family. Claire decided not to tell Sarah that her father is in prison. She says Daddy has a new job and has to stay away. She takes Sarah to visit, and says this is where he works. Sarah's childcare centre reports that she has started wetting herself regularly. Claire is struggling to juggle work, childcare and the trips to the prison, and money is tight. She tells no one, although the case was in the local news.",
    extra: [["Claire, Mum", "I had postnatal depression after Sarah was born, and since her father went to prison my anxiety has been getting worse. I don't claim any help with the cost of prison visits. I don't know if there is any."],
      ["Sarah", "At group time, Sarah said that Daddy had gone away. Claire had told the centre that he had moved away for work, so no one asked more. Then a staff member saw a news story about Sarah's father, and wondered aloud whether this was behind the change in Sarah."]],
    notes: ["Family: Claire, Sarah (3), and Sarah's father in prison.", "Agencies: the childcare centre, and the prison through visits. No one else yet.", "Strengths: Claire keeps Sarah in contact with her father. Sarah is close to him. The childcare centre has noticed.", "Needs: Sarah is confused. What she is told doesn't match what she sees. Claire needs help with her own anxiety, with money and travel, and with how to tell Sarah the truth."],
    orig: "Case study 1: Claire's ex-partner had received a 5 year sentence. Claire's daughter Sarah was 3 when her father was arrested. Before the arrest, Sarah had spent significant periods of time with her father as he shared the childcare responsibilities. No other agencies were involved with the family prior to the arrest. Claire decided not to tell her daughter that her father was in prison and instead told her that Daddy had got a new job which meant he had to stay away. Claire took her daughter to see her father but continued to tell her daughter that this was where her father was working. Sarah's nursery reported that she had begun wetting herself regularly. Claire struggled to juggle work commitments with childcare and travel to the prison for visits and was finding it difficult to cope financially. She tried not to tell anyone about Sarah's father's imprisonment, although the case had been covered in the local media." },
  { id: "c2", name: "Kim's children and their Nan", line: "Three children move in with grandparents",
    text: "Kim is serving her first prison sentence, 15 months. She has three children, aged two, six and eight. None of them has contact with their fathers. All three went to live with their grandparents, and had to change schools. Their grandmother gave up her part-time job to care for them, and finds it very hard and exhausting. The women's prison at Risdon Vale is a two-and-a-half-hour drive from where they live. At the first visit the youngest became distressed, and their grandmother struggled to manage all three. There have been no visits since. Kim told her mother that was fine: she didn't want the children seeing her in prison anyway. In the months since, the six-year-old has become very withdrawn, the two-year-old clingy, and the eldest's behaviour at school has got much worse.",
    extra: [["Grandmother", "I'm worn out, in body and mind. I'm embarrassed to take the baby to playgroup, because I don't want people asking where my daughter is. I'm really worried about her, but I don't tell anyone. I just feel so ashamed. I'm out of my depth with the older two, and I often leave them on the computer."],
      ["Eight-year-old son", "I'm really angry with Mum for making me live with Nan and leave my friends. I hate my new school and I can't concentrate. I do miss Mum, but I don't let my brother and sister know, because I have to show them it's all okay. I know Nan finds it hard to look after us. I feel bad for her too."]],
    notes: ["Family: Kim (in prison), her children aged 2, 6 and 8, and their grandparents.", "Agencies: two schools (old and new), and the prison. Perhaps Centrelink, now that Nan has stopped work.", "Strengths: the children are together, with family. The eldest looks out for the younger two. Nan is committed.", "Needs: contact with Mum has stopped, and nobody chose that for the children. Nan needs practical and emotional support, and help with money. The eight-year-old is carrying too much. The new school needs to know enough to help."],
    orig: "Case study 2: Kim had received her first 15 month prison sentence. Kim had 3 children 2, 6 and 8 years old. None of the children have any contact with their fathers (there are 2 different fathers). All the children went to live with their Grandparents while their mother was in prison – they had to move schools. The Grandmother gave up her part time job to care for the children, but found the parenting role very difficult and exhausting. Kim was placed in a prison a 90 minute car journey away from her children. Following the first visit, where the youngest child became distressed and the Grandmother found it difficult to cope with all 3 children, Kim did not receive any further visits. Kim told her mother that this was okay as she didn't want her children to see her in prison anyway. The 6 year old became very withdrawn in the following months, the 2 year old increasingly clingy, while the oldest son's behaviour at school deteriorated significantly." },
  { id: "c3", name: "Becky, Simon and the baby", line: "A new mother, and a release date coming",
    text: "Simon was 21 when he was sent to prison for 18 months. His partner Becky was six months pregnant. At first she visited every week. Then Simon was moved to Risdon, more than three hours from her home in the north-west. With a newborn and no car, the trip is very hard, but Becky feels she should visit as often as she can. She has become depressed, and the relationship is breaking down. Each feels the other doesn't understand. Now Simon's release is getting close, and Becky is more and more anxious about how he will fit into the routine she has built as a parent.",
    extra: [["Becky, Mum", "I've coped quite well without Simon at home. It's been lovely not having the tension or the arguments. The baby sleeps in my bed. It's easier, and I like it. I'm worried Simon won't approve. His family are putting a lot of pressure on me to make a good home for him to come back to, because he's had a hard time. They don't see that I've had a hard time too."]],
    notes: ["Family: Becky, the baby, and Simon. Simon's family in the background.", "Agencies: the Child Health and Parenting Service, a GP, and Community Corrections once Simon is released.", "Strengths: Becky has built a settled routine and is coping as a parent. She has kept up contact despite the distance.", "Needs: Becky's mental health. Somewhere to say what she really feels about release. The tension and arguments before prison are worth a gentle safety question. Simon has never lived with his child."],
    orig: "Case study 3: Simon was 21 when he was sent to prison for 18 months. His partner Becky was 6 months pregnant when he was convicted. Becky tried to make weekly visits, however after 3 months Simon was moved to a prison 50 miles away. Becky found the journey on public transport difficult with a new born baby, but felt pressure to visit Simon as often as possible. Becky began to become depressed and her relationship with Simon began to break down as neither felt the other understood their situation. As the end of Simon's sentence drew near Becky grew increasingly anxious about him coming home and how he would fit into her new routine as a parent." },
  { id: "c4", name: "Shelley", line: "An eleven-year-old who can't have contact with Dad",
    text: "Shelley is 11. She lived with her mother, her father and her six-year-old brother. Her father had a well-paid job and her mother was at home. He was convicted of a sexual offence against a child in their extended family. Shelley has been told that her father can't contact her or her brother at all: no calls, no letters, no visits. The extended family has pulled away, and Shelley's mother is isolated. After the sentencing was in the local news, the family was abused in the street and their garage door was graffitied. Her mother's mental health has got much worse, and she has moved the family out of the area. Shelley has taken on caring for her brother, because her mother finds it hard to cope. Shelley is showing clear signs of loss, anger and disbelief that she can't see her father.",
    extra: [["Mother", "I still find it hard to believe what happened, and that they found him guilty. I still speak to him on the phone, but it's hard, because I know he can't speak to the kids. I don't talk to our old friends any more. I haven't told anyone in our new town. I just say I'm separated. I'm confused and tired, and frightened about how I'll keep paying the bills. I don't know where to turn."],
      ["Shelley", "I didn't go to school today. I told Mum I felt sick. I just couldn't face it. I feel like everyone knows about my Dad, even at my new school. I don't really understand why they sent him to prison or why I can't speak to him. I know he hurt someone, but that isn't the Dad I know. No one has asked me what I think. I can't talk to Mum because she's so tired all the time. I can't sleep. I feel angry with everyone, like inside I'm screaming."]],
    notes: ["Family: Shelley (11), her brother (6), their mother, and their father in prison. Extended family estranged.", "Agencies: probably Child Safety at some point, police, the new school. Perhaps a GP.", "Strengths: Shelley cares for her brother and can say how she feels. Her mother got the family away from the abuse.", "Needs: Shelley has had a loss she isn't allowed to mourn, and nobody has asked what she thinks. She needs honest information at her level, and to hear that it isn't her fault. She is carrying a carer's load. Her mother needs mental health and money help. Safeguarding comes first: contact is restricted for a reason, and her mother's continuing belief in her husband matters."],
    orig: "Case study 4: Shelley is 11 and lives with her mother and father and 6 year old brother. Her father worked in a well-paid position and her mother stayed at home. Shelley's father was committed of a sexual offence against a minor within their extended family. Shelley has been informed that her father is now not able to contact her or her brother via telephone, mail or prison visit. Shelley's extended family have distanced themselves from her family and Shelley's mother has become isolated. Following local media coverage of the sentencing the family were victims of verbal abuse and their garage door was graffiti-ed. Shelley's mother's mental health has declined significantly and she has moved the family out of the area. Shelley has taken on a caring role towards her brother as her mother finds it difficult to cope and Shelley is exhibiting clear signs of loss, anger and disbelief that she is unable to see her father." },
  { id: "c5", name: "Liz, James and his brother", line: "Arrested at home, in front of the children",
    text: "A week ago, Liz's husband was arrested at home, in front of their two sons, aged three and seven. It was his first arrest, and the boys saw a confrontation between their father and the police. He didn't come home. He is being held on remand. The older boy, James, broke down in class and told his teacher that the police had taken his Daddy away. The family will visit next week. Liz is very apprehensive, and hasn't been able to talk to the boys about it, because she gets too upset. She will take them out of school and childcare for the visit, and has decided not to tell either place why.",
    extra: [["Liz, Mum", "I'm not going to tell the kids what's happened. I'm sure it's a mistake. My husband says he's done nothing wrong and I believe him. The boys will be fine once they see their Dad. There's no point telling them or the school, because he'll probably be home soon. I'll just say Dad has gone to work for a few weeks in a special place with lots of security, because it's top secret."],
      ["James, 7", "I was really scared when the police came in. They shouted at Daddy and made him leave our house. Daddy was angry too, and Mummy was crying. I don't know where Daddy is, and I'm worried the police might be hurting him. Might they take Mummy away? At school, when I think about it, sometimes I start crying. Mummy says the police made a mistake and Daddy is working in a new place where we can see him on the weekend. I hope there are no police where he's working, and they won't hurt Mummy and me when we go."]],
    notes: ["Family: Liz, James (7), his brother (3), and their father on remand.", "Agencies: police, the school (James's teacher already knows something), childcare, the prison.", "Strengths: James told a trusted adult. Liz is taking the boys to see their father. The teacher is an ally waiting to be used.", "Needs: James saw the arrest and is frightened of the police. The story he's been given will collapse at the prison gate, where there are uniforms and searches. Liz needs support for her own shock before she can talk to the boys. The first visit needs preparing for."],
    orig: "Case study 5: A week ago, Liz's husband was arrested in the family home in front of her 2 sons – a 3 year old and a 7 year old. This is the first time her husband has been arrested and the children witnessed a confrontation in between their father and the police. Her husband did not return home after arrest and was taken into remand custody in their local prison. Her oldest son, James, told his teacher that his Daddy had been taken away by the police after he broke down in the classroom. The family are going to visit their father next week. Liz is very apprehensive and has not been able to talk to the boys about it as she gets too upset. She will be taking her sons out of school and nursery to make the visit but has decided not to tell either establishment that she is visiting their father in prison." }
];

/* ---------- 1 ---------- */
PT.modules.push({ id: "welcome", title: "Welcome", short: "What this course is, and how it works", mins: 5, color: "#1B2A3A", icon: "door", blocks: [
  { quote: "It's not just the prisoner that's punished is it? It's the whole family.", who: "Mother, quoted in the Practitioner's Guide" },
  "This course is for anyone in Tasmania whose work brings them into contact with children and families: teachers, child safety and family workers, health workers, police, corrections staff, youth workers, chaplains and volunteers.",
  { h: "What you'll be able to do" },
  ["See these children as people with rights of their own.", "Understand what a family member's offending does to a child and to a family.", "Build these children's needs into the assessments you already do.", "Work with more confidence with parents, carers and children.", "Know which Tasmanian services and tools to reach for."],
  { h: "How it works" },
  ["Nine short modules. About two and a half hours in all.", "Stop whenever you like. Your place is kept on this device.", "You'll follow one family through the course, and build a support plan for them.", "At the end there's a short knowledge check and a certificate to print."],
  { tip: "Nothing you type leaves this device. There are no accounts and no tracking. Your notes are kept in this browser only, so you can pick up where you left off. You can clear them at any time under About this course." },
  { h: "The course text" },
  "The course follows Onesimus's Practitioner's Guide. Its tools are in the Field Guide, a phone guide you can keep using after the course.",
  { links: [["Open the Field Guide", PT.FG]] },
  { flag: "The face-to-face workshop ran for about five hours with a break. This online edition keeps every exercise, in shorter form. To decide: whether it stands alone, or is paired with a face-to-face session. An introductory course (Hidden Sentence) is planned as the stage before this one." },
  { orig: "Aim: To enable practitioners to develop effective assessment and practice skills to support CAPO within a whole family approach. Learning outcomes: Increased understanding of the importance of supporting CAPO within a children's rights perspective. Increased understanding of the impact of the offending of a key attachment figure on child development and family function. Increased ability to incorporate needs of CAPO into professional assessments. Increased knowledge, confidence and skills in working with children and families affected by the offending of a key attachment figure. Increased knowledge of resources and services available to support CAPO." }
] });

/* ---------- 2 ---------- */
PT.modules.push({ id: "rights", title: "A rights-based approach", short: "Children's rights, stigma and discrimination", mins: 20, color: "#2F6F73", icon: "shield", blocks: [
  "Children with a family member in prison have been called the forgotten victims of the justice system. They have done nothing wrong, yet they live with the consequences. A rights approach treats them as people with rights of their own.",
  { h: "Watch: \"Because it's our right\"" },
  { video: { title: "Because it's our right", by: "Children of Prisoners Europe", url: "https://childrenofprisoners.eu/because-its-our-right/", note: "A short animation, made with children, about a child's right to stay in contact with a parent in prison.", credit: "This film was made by Children of Prisoners Europe and sits on their website. Onesimus commends their resources to anyone working with children and families of people in prison." } },
  { reflect: { id: "r-video", prompt: "After watching: which right in the film is hardest for a child in Tasmania to exercise? Why?", pointsTitle: "Points from the film's discussion guide", points: ["Article 9 of the UN Convention on the Rights of the Child: every child has the right to keep contact with a parent, unless that is against the child's best interests.", "Children often don't know they have this right.", "A child may feel sad and frustrated, and can still feel happy and laugh. All of those feelings are allowed.", "There are many ways to keep in touch: letters, drawings, phone calls, schoolwork sent in, and visits where possible."] } },
  { h: "Five rights that matter most here" },
  ["Article 2: no discrimination, whatever family a child comes from.", "Article 3: the child's best interests come first.", "Article 9: not separated from parents unless it's in their best interests, and contact kept up unless it would harm them.", "Article 12: a say in what affects them, and to be taken seriously.", "Article 16: privacy for their family and home life."],
  "In Tasmania, the Child and Youth Safe Standards ask the same of every organisation that works with children: involve children in decisions that affect them.",
  { h: "Exercise: stigma and discrimination" },
  "Read what these people said. Some are family members. Two are prison officers.",
  { quote: "There is stigma, and we women and children suddenly have a flaw, for which we are not responsible. We can't go into public with this flaw.", who: "Mother (Children of Imprisoned Parents, 2014)" },
  { quote: "If I tell my Dad's in prison I will get told off by my Mum.", who: "Girl aged 7 (Every Night You Cry, 2009)" },
  { quote: "I can't even go to my own MP because my family name stinks so much in my own town. I've got no criminal record myself, but we're just all tarred with the same brush.", who: "Sister of a man in prison (The Guardian, 2016)" },
  { quote: "I think if you bring children now who are five years old to prison to see their parents, see them in fifteen years time… ninety nine percent of them will be breaking the law, or have no respect for themselves anyway.", who: "Prison officer" },
  { quote: "It's like something that's like stuck to you, like carries around, like a baggage, that people can't really see.", who: "Young person (i-HOP consultation, 2016)" },
  { reflect: { id: "r-stigma", prompt: "What does stigma do to a family: to their wellbeing, to how others treat them, and to whether they ask services for help?", pointsTitle: "What workshop groups usually say", points: ["Wellbeing: shame, secrecy, isolation, low self-esteem. Children learn to hide.", "How others treat them: gossip, exclusion, bullying, and being judged by workers as well as neighbours.", "Access to services: families don't ask, or don't tell the whole story, so help comes late or not at all.", "A worker's own assumptions matter. The officer's prediction is the kind of low expectation children pick up."] } },
  { quiz: { id: "q-rights", q: "A mother says, \"I don't want the school to know.\" What does a rights-based approach suggest?", options: ["Tell the school anyway, because it's in the child's best interests.", "Respect her choice, explain how the school could help, and ask what the child wants.", "Say nothing more about it."], answer: 1, why: "It's the family's information, and privacy is one of the child's rights. But the child also has a right to support and a say. Explain the benefits and let the family decide. Safeguarding concerns are the exception." } },
  { flag: "Videos: Onesimus holds copies of both course films. They aren't Onesimus's to publish, so this draft links to the makers' own pages. Both film links were supplied by Norm and checked live on 17 Nov 2026. Each film is credited to the organisation whose site it sits on. To embed either film in the course, ask its maker first. Quotes are from the workshop's handout 01; the second prison officer quote is left out for length." },
  { orig: "Ensuring a Rights-based Approach. Recognising the rights of children of prisoners. Ensuring equal opportunities, free of discrimination. 'Discrimination is a rope that binds the soul and diminishes its light. Rejection becomes a part of daily life, stifling individual expression and human achievement.' (Taslima Nasrin, human rights activist). Stigma and Discrimination Exercise: What impact does stigma and discrimination have on families? In terms of their wellbeing? In terms of how they are treated by others? In terms of their access to services?" }
] });

/* ---------- 3 ---------- */
PT.modules.push({ id: "needs", title: "When needs can't be met", short: "Maslow's pyramid and a family member's offending", mins: 10, color: "#B8894A", icon: "steps", blocks: [
  "The psychologist Abraham Maslow described human needs as a pyramid. The basic needs at the bottom, like food, sleep and safety, have to be met before we can do much about the ones above them.",
  { ol: ["Body: food, sleep, warmth.", "Safety: a secure home, income and health.", "Belonging: relationships.", "Esteem: confidence, respect, achievement.", "Reaching potential: growing into who they could be."] },
  { h: "Exercise: where does it hit?" },
  "Here are twelve things that can happen to a family when someone offends. For each one, choose the level of need it affects most. Some could fit more than one level. The exercise is to think about it, not to score.",
  { sort: { id: "s-maslow", bins: ["Body", "Safety", "Belonging", "Esteem", "Potential"], items: [
    { t: "The family slides into poverty, which affects food and quality of life.", bin: 0 },
    { t: "Stress and worry disturb sleep.", bin: 0 },
    { t: "The offence brings threats or abuse against the family.", bin: 1 },
    { t: "Routines are disrupted: childcare, getting to work.", bin: 1 },
    { t: "The family is at risk of losing its housing.", bin: 1 },
    { t: "A key attachment figure is gone.", bin: 2 },
    { t: "The child cuts themselves off from friends, becomes secretive, or is bullied.", bin: 2 },
    { t: "Care becomes inconsistent.", bin: 2 },
    { t: "The child is labelled because of stigma, which lowers their confidence.", bin: 3 },
    { t: "The child starts to see themselves as \"bad too\".", bin: 3 },
    { t: "The child comes to reject people in authority.", bin: 4 },
    { t: "The line between secrets and lies blurs when the truth isn't told.", bin: 4 }
  ] } },
  { tip: "Safeguarding: think about where these needs stand for the child in front of you. One unmet need, or a combination, may mean a safeguarding referral." },
  "Problems the family already had, such as money trouble or poor mental health, can get worse too.",
  { orig: "Recognising children of offenders as potentially vulnerable. Q. How can parental offending prevent a child's needs being met at each level? Exercise: Impact of parental offending on meeting a child's needs. Potential barriers to meeting needs created by parental offending." }
] });

/* ---------- 4 ---------- */
PT.modules.push({ id: "family", title: "The pressure on a family", short: "What a parent or carer is carrying", mins: 20, color: "#8A4F7D", icon: "chat", blocks: [
  { h: "Six things to hold on to" },
  ["Offending can make worse the problems that were already straining a family.", "Take a whole-family approach.", "The impact differs from one family member to another.", "The impact changes over time.", "There can be good effects as well as bad. If the person was violent or chaotic, prison may bring relief.", "Hear the voice of the child."],
  { h: "Why needs differ from carer to carer" },
  ["Their emotional resilience, and their physical and mental health.", "Their relationship with the children, and their parenting skills.", "The family and community support around them.", "Their culture and community.", "How independent they are, with money and day-to-day things.", "How much childcare they have to do.", "Their relationship with the person who offended.", "What the offence was, the media coverage, and how the community responds.", "Where the person is up to in the justice system."],
  { h: "Exercise: one mother's two years" },
  "In the workshop, sixteen cards are handed out one at a time. Each is something that happens to one mother. Turn them over one by one, and notice what builds up.",
  { cards: { id: "p-cards", items: [
    "I am a mother of two children, aged seven and three. I'm married. My husband works full time as a builder, and I work part time in a supermarket.",
    "My husband is arrested for assault. He gets bail. We wait twelve months for his sentence.",
    "I go to court and my husband is sentenced to five years. I watch him leave the court. Two days later I still don't know where he has been taken.",
    "The local paper runs a story about my husband's offence. It has his photograph, and the name of our street.",
    "I open a letter from our landlord. We are behind on the rent. The lease is in my husband's name.",
    "My seven-year-old daughter starts waking in the night, crying for her father. In the day she gets very anxious when we're apart, and at home she needs to be with me all the time.",
    "My husband is held at Risdon. We live in the north-west. It's more than three hours' drive each way.",
    "I ask for more hours at work, because we can't manage on my pay. Now I need more childcare.",
    "My husband asks me to put $150 into his prison account.",
    "My three-year-old starts acting up at childcare, biting and hitting other children.",
    "I visit my husband with the children. He has a bruised face. He is upset with me because we arrived late.",
    "My husband hasn't called home for five nights in a row. My daughter says she misses her Dad, and blames me for not letting her speak to him.",
    "My daughter isn't invited to a birthday party at school. Her teachers say she is withdrawn and not concentrating.",
    "It's my youngest's fourth birthday. I take both children to see Dad as a treat, taking my daughter out of school. After three hours' travel, we're told the visit can't go ahead. No one had let me know.",
    "The prison tells me my husband can only have non-contact visits, because of a security investigation. I see him in a booth, through a screen.",
    "For the last eighteen months of his sentence, things settle. The kids and I visit every second Saturday."
  ], end: "Sixteen cards, one family. None of them is unusual." } },
  { reflect: { id: "r-pressure", prompt: "If this mother walked into your service at card 8, what would you see? What wouldn't you see?", pointsTitle: "What workshop groups usually notice", points: ["You'd probably see a tired mother asking for more hours, or a child acting up. You wouldn't see the prison.", "Money, housing, the children's behaviour and her own exhaustion all arrive together.", "Nobody is told anything: where he is, that the visit is cancelled.", "The children's distress lands on her. So does his.", "She has had no say in any of it."] } },
  { flag: "Cards adapted from handout 03 for Tasmania: ABH is now assault; the £150 postal order is now $150 into a prison account; tax credits became needing more hours; \"moved to a training prison 150 miles away\" is now Risdon from the north-west; \"moved prison, no one told me\" is now a cancelled visit; \"closed visits\" is now non-contact visits; the last card no longer has a move to a local prison. TO CONFIRM with TPS: the term for non-contact visits, and how families are told when a visit is cancelled." },
  { orig: "Handout 03, pressure on a family (16 cards): I am a mother of 2 children. They are 7 and 3 years old. I am married and my partner works full time as a builder. I work part-time in a supermarket. | My husband is arrested for ABH. He is given bail awaiting sentencing. We wait 12 months for his sentence to be passed. | I attend court and my husband is sentenced to 5 years. I see him leave court. 48 hours later I still do not know where he has been taken to. | My local newspaper includes an article about my husband's offence. The article includes a photograph of my husband and the name of my street. | I open a letter from our landlord – we are in rent arrears. The rent is in my husbands' name. | My 7 year old daughter starts waking in the night crying for her father. During the day she gets very anxious when separated from me and when I am at home she needs to be with me all the time. | My partner is moved to a training prison so that they can attend a specialist course. The prison is 150 miles away. | I have to request additional hours at work to increase my income so that I can be eligible for tax credits. | My partner asks me for a postal order for £150. | My 3 year old begins to display disruptive behaviour at nursery, biting and hitting other children. | I visit my husband with the children. He has a bruised face, he is upset with me because I arrived late into the visit hall. | My husband hasn't called home for the 5th night in a row. My daughter complains that she misses her Dad and blames me for not letting her speak to him. | My daughter does not get invited to a birthday party at school. Teachers report that she is withdrawn and is not concentrating. | It is my youngest child's 4th birthday – I take both children to see Dad as a Birthday treat (taking my daughter out of school). I get to the prison after travelling for 3 hours. My husband has just moved prison – no one had let me know. | I am informed by the prison that my husband will only be able to receive closed visits as a security investigation is underway. I visit him in a booth separated physically by a screen. | For the last 18 months of his sentence my husband is placed in a local prison 30 minutes from home. Me and the kids visit the prison every week on a Saturday morning." }
] });

/* ---------- 5 ---------- */
PT.modules.push({ id: "children", title: "The impact on children", short: "Timing, attachment, grief and the signs", mins: 15, color: "#4B7A5E", icon: "child", blocks: [
  { quote: "I'm so angry because you promised you would come back and take us and we would live with you. You left me having nightmares. I didn't know if you were safe, and I was really scared.", who: "Young person, quoted in the Practitioner's Guide" },
  { h: "It comes and goes" },
  "The impact on a child changes over time, and shows most at certain moments:",
  ["when the family member is arrested", "when they go to court", "when the child finds out about prison", "just before or after a visit", "on birthdays, Father's Day and Mother's Day", "when the person comes home for a visit, or is released"],
  { h: "Attachment" },
  { quote: "Parent–child relationships are undermined, disrupted and damaged by the court and prison systems.", who: "Galloway et al. 2014" },
  "Babies and young children need warm, consistent care. Prison removes a parent altogether. But attachment can also be damaged by patchy care around the offending, by restricted contact, and by confused stories about where the person is.",
  { h: "A grief nobody sees" },
  "Researchers call it disenfranchised grief: a loss that can't be openly acknowledged, publicly mourned or socially supported. Because prison carries a stigma, nobody brings a casserole or sends a card. It has been compared to a death without the chance to mourn.",
  "Like children who've had someone die, these children need help to accept the loss, feel the pain of it, adjust to life without the person at home, and remember them.",
  { h: "Signs you might see" },
  ["moodiness, aggression, or chattering more than usual", "bullying, or trouble with other children", "seeming withdrawn", "poor concentration, tiredness, losing interest in schoolwork", "hostility to teachers and others in authority", "bedwetting", "separation anxiety", "using alcohol or other drugs", "self-harm, or talk of suicide"],
  { warn: "If a child talks about self-harm or suicide, act on it that day. Follow your organisation's procedure. If they're in danger now, call 000." },
  { tip: "These signs aren't proof of anything on their own. Many children show some of them for other reasons. They are a reason to ask, gently, how things are going." },
  { quiz: { id: "q-grief", q: "A nine-year-old has become withdrawn since her father went to prison. Her aunt says, \"She's fine. She never mentions him.\" What's the most likely reading?", options: ["She has adjusted well.", "She may be grieving a loss she doesn't feel allowed to talk about.", "She didn't have a close relationship with him."], answer: 1, why: "Silence often means the subject isn't safe to raise, not that it doesn't hurt. That is disenfranchised grief. Give her a way to talk that doesn't depend on her bringing it up." } },
  { quiz: { id: "q-timing", q: "When might a child's distress show most?", options: ["Only at the time of arrest.", "Mainly on prison visit days.", "At many points, including birthdays, visits, court dates and release."], answer: 2, why: "The impact rises and falls with events. Release can be as unsettling as arrest." } },
  { orig: "Impact on children. The impact on children, might vary over time and become more apparent at certain points: When a family member is arrested. When a family member is attending court/standing trial. When they find out about a family member's imprisonment. Prior to or directly after visiting a family member in prison. When there are special events such as birthdays, father's/mother's days. There is a home visit by the family member in prison. A family member is released from prison. Attachment: 'Parent-child relationships are undermined, disrupted and damaged by the court and prison systems.' (NSPCC, 2014). Disenfranchised grief: 'The grief experienced by those who incur a loss that is not, or cannot be, openly acknowledged, publicly mourned or socially supported.' (Families Outside)." }
] });

/* ---------- 6 ---------- */
PT.modules.push({ id: "assess", title: "Assessing needs", short: "Choose a family and get to know them", mins: 15, color: "#6B4E8A", icon: "wheel", blocks: [
  "In the workshop, each group is given a family to work with for the rest of the day. Choose one now. You'll come back to them in the next two modules.",
  { cases: true },
  { flag: "Case studies adapted from handout 04 and the extra information cards (handout 07). Changes: nursery is now childcare; prison distances are Tasmanian (Risdon from the north and north-west); \"local prison\" removed. The course notes on each family are new, written for this edition, and need review by Norm." }
] });

/* ---------- 7 ---------- */
PT.modules.push({ id: "parents", title: "Supporting parents and carers", short: "Approach, telling the children, and a support plan", mins: 25, color: "#9A3B2E", icon: "help", blocks: [
  { quote: "All we want as a family is just to know what to do, how to go about things, because we don't know. No one tells you anything.", who: "Mother, quoted in the Practitioner's Guide" },
  { h: "How to approach a parent or carer" },
  ["Be non-judgemental and understanding.", "Be persistent. Trust can take time.", "Listen to their story, and acknowledge it.", "Know the difference between what you need to know and what you'd like to know.", "Make the safeguarding checks you need to.", "Offer support in small, realistic steps. Don't add to the pressure."],
  { quiz: { id: "q-need", q: "You're meeting a carer for the first time. Which question do you not need to ask?", options: ["\"What would help most right now?\"", "\"What exactly did he do?\"", "\"Who else is supporting you and the children?\""], answer: 1, why: "The details of the offence are usually something you'd like to know, not something you need. If the carer wants to tell you, they will. Safeguarding is the exception: if there's a risk to a child, you do need to know." } },
  { h: "Telling the children" },
  "It's the parent's choice what to tell their children, and when. Your job is to help them think it through.",
  { reflect: { id: "r-truth", prompt: "What are the benefits of helping a parent or carer tell the children the truth?", pointsTitle: "From the guide", points: ["Children usually know something is wrong. What they imagine can be worse than the truth.", "They may find out anyway: from other children, the news, or the visit itself.", "The truth, told at their level, lets them ask questions and trust the answers.", "It takes away the strain of keeping a story going.", "It lets other adults, like a teacher, help."] } },
  "Parents may find it hard to tell children because they:",
  ["want to protect the child from being upset, scared or anxious", "are finding it hard to cope themselves", "want to protect the child from stigma", "want to shape how the child sees the person in prison", "don't want the child to talk to anyone else about it", "find it too painful, or don't know how to explain it"],
  { h: "What support might a carer need?" },
  ["understanding the justice system", "relationship guidance", "parenting", "money", "housing", "kinship care", "employment", "health: mental, emotional and physical", "childcare"],
  "The Field Guide lists checked Tasmanian services for each of these, grouped to match the Support Wheel.",
  { links: [["Where to get help", PT.FG + "#help"], ["Parent / Carer Support Wheel", PT.FG + "#wheel-parent"], ["Telling the children", PT.FG + "#telling"]] },
  { h: "Exercise: a support plan for the parent or carer" },
  { caseref: "Think about the parent or carer in your family. Open the Parent / Carer Support Wheel in the Field Guide and rate each area as you think they might. Then choose the one or two areas that matter most, and plan a small first step for each." },
  { plan: { id: "plan-parent", example: ["Information about the prison", "Feel confident about what visiting my husband will be like", "Mum reads the Prison Service's visiting page and notes any questions. Worker rings the Visitor Reception Centre to ask what support there is for families.", "Mum; worker", "At home, this week"] } },
  { tip: "A good plan is small. One or two areas, one step each, a name against every step, and a date. The carer chooses the area." },
  { orig: "Approach with parents/carers: Non-judgemental and understanding. Be persistent – may take time to build trusting relationship. Listen to and acknowledge their own story. Recognise the difference between the information that you need to know and the information that you want to know. Undertake necessary safeguarding checks. Provide support and identify actions in manageable, realistic steps (do not add to the pressure!). Telling the children: Q. What are the benefits of supporting the parent/carer to tell children the truth? Parents have the choice what they tell their children and when. Parents/carer may need support to understand why telling their children the truth is important. They may also require support to talk to their children." }
] });

/* ---------- 8 ---------- */
PT.modules.push({ id: "kids", title: "Supporting children", short: "Their questions, their safety, and a plan of their own", mins: 25, color: "#2E6CA4", icon: "child", blocks: [
  { quote: "It's affecting you not them, they have to know how you feel not how they think you feel…", who: "Young person, quoted in the Practitioner's Guide" },
  { h: "What children may need help with" },
  ["naming and sharing their feelings", "managing their own behaviour and feelings", "getting answers to their questions and worries", "keeping in contact with the person in prison", "getting on with friends and the wider community", "coping with changes at home"],
  { quote: "If you do nothing but strive for the deepest possible understanding of a child and if you communicate that understanding, that experience can be life-changing.", who: "Kahn, 1991" },
  { h: "Questions children want answered" },
  ["Why was my family member sent to prison?", "What happens at court? Can I go?", "Will other people know?", "Does this mean I'm bad too? Do they still love me?", "How long will they be gone?", "Can I stay in touch? How, and how often?", "What is it like in there? Are they safe? What do they eat?", "What is a visit like?", "What will it be like when they come home? Will they be different? Will they go away again?"],
  { quiz: { id: "q-working-away", q: "A carer has told a six-year-old that Dad is \"working away\". The child asks you when Dad's job will finish. What do you do?", options: ["Tell the child the truth. They have a right to know.", "Work with what the child has been told, support their feelings, and talk with the carer about being more open.", "Change the subject."], answer: 1, why: "What the child is told is the parent's decision. You can still help the child with missing Dad. Then, separately, help the carer weigh up the benefits of telling the truth." } },
  { h: "Tools for talking with children" },
  "Simple activities help a child say what's going on without a question-and-answer interview: Dudley the Dog, Three Islands, Faces, Three Houses, a letter template and a memory box. All six are in the Field Guide.",
  { links: [["Tools for talking with children", PT.FG + "#kidtools"], ["Taking a child to visit", PT.FG + "#visit"], ["Child / Young Person Support Wheel", PT.FG + "#wheel-child"]] },
  { h: "Keeping children safe" },
  "Some children can't, or shouldn't, have contact with the person in prison. Contact may be restricted when:",
  ["the child was the victim of the offence", "the offence was against another child, or was a serious assault", "a court order limits contact", "the child is in care and the carers can't take them", "the person in prison is under a temporary restriction on visits"],
  { warn: "Worried about a child? Call the Strong Families, Safe Kids Advice and Referral Line on 1800 000 123. If a child is in immediate danger, call 000. Follow your own organisation's procedures too." },
  { quiz: { id: "q-nocontact", q: "A child can't have any contact with her father because of the nature of his offence. What does she most need from you?", options: ["To be told as little as possible.", "Help with the loss, honest information at her level, and to hear clearly that it isn't her fault.", "Reassurance that contact will start again soon."], answer: 1, why: "Where contact isn't possible, the child still has a loss to cope with. Don't promise what you can't know. Do tell her it isn't her fault." } },
  { h: "Exercise: a support plan for the child" },
  { caseref: "Think about one child in your family. Open the Child / Young Person Support Wheel and rate each area as you think they might. Then plan one or two small steps. Ask yourself: has anyone asked this child what they think?" },
  { plan: { id: "plan-child", example: ["Remembering Dad", "Have ways to think about Dad and feel happy", "Start thinking about happy things I've done with Dad to put in my memory box. Worker finds a box we can decorate next session.", "Sam; worker", "At home, this week"] } },
  { flag: "Safeguarding list reworded from the slides: \"child in need / child protection plan\", \"LAC\" and \"adopted\" are UK terms, replaced as in Chapter 2.4. TPS rules on children visiting are on the verification checklist." },
  { orig: "Supporting children. Children may need support to: identify and share their feelings; manage their own behaviour and feelings; answer questions and address their anxieties; maintain contact with their family member; manage relationships with their peers and wider community; cope with changes in family/home environment. Emotional Containment: \"If you do nothing but strive for the deepest possible understanding of a child and if you communicate that understanding, that experience can be life-changing\" (Kahn, 1991)." }
] });

/* ---------- 9 ---------- */
PT.modules.push({ id: "finish", title: "Next steps", short: "A last film, your action plan, and your certificate", mins: 15, color: "#1B2A3A", icon: "print", final: true, blocks: [
  { h: "Watch: a poem that reads two ways" },
  { video: { title: "Reversible Thinking", by: "Families Outside (Scotland)", url: "https://www.familiesoutside.org.uk/reversible-thinking-video/", note: "A short poem about a child with a parent in prison. Read from the top it says one thing. Read from the bottom it says another.", credit: "This film was made in partnership with Families Outside and sits on their website. Onesimus commends their resources to anyone working with children and families of people in prison." } },
  "The workshop ends with this film, and a question: what would it take to reverse the writing on the wall for the children you work with?",
  { h: "Your action plan" },
  { reflect: { id: "r-action", prompt: "Write one thing you will do differently in your own work, and one thing you will raise in your team or organisation.", pointsTitle: "Ideas from past workshops", points: ["Add one question to our intake form: has anyone important to this child gone to prison?", "Put the Field Guide on my phone and show a colleague.", "Find out who in my organisation knows the Tasmania Prison Service's visiting rules.", "Ask a child what they think, before the meeting about them."] } },
  { h: "Knowledge check" },
  "Nine questions. You need seven to unlock your certificate. You can try again as often as you like.",
  { check: [
    { q: "Under Article 9 of the UN Convention on the Rights of the Child, a child separated from a parent has the right to…", options: ["be told everything about the offence", "stay in contact with that parent, unless it's against the child's best interests", "choose where the parent is held"], answer: 1 },
    { q: "Who decides what children are told about a family member being in prison?", options: ["The worker", "The school", "The parent or carer"], answer: 2 },
    { q: "\"Disenfranchised grief\" means…", options: ["a loss that can't be openly acknowledged or mourned", "grief that lasts longer than a year", "grief felt by the person in prison"], answer: 0 },
    { q: "In Tasmania, you're worried about a child's safety but they're not in immediate danger. You…", options: ["wait and see", "contact the Advice and Referral Line on 1800 000 123, and follow your organisation's procedures", "ring the prison"], answer: 1 },
    { q: "On the Support Wheel, a rating of 5 means…", options: ["\"I feel good about this\"", "\"Crisis: I need help with this\"", "five people are involved"], answer: 1 },
    { q: "A good support plan…", options: ["covers every area on the wheel", "has one or two areas, small steps, a name and a date", "is written by the worker after the meeting"], answer: 1 },
    { q: "A family asks you a question about prison rules that you can't answer. You…", options: ["give your best guess", "say you don't know, and point them to the Tasmania Prison Service or find out", "tell them to ask the person in prison"], answer: 1 },
    { q: "When a child can't have contact with the person in prison, they need…", options: ["help with the loss, and to hear that it isn't their fault", "to forget about the person", "a promise that contact will resume"], answer: 0 },
    { q: "Which of these is a reason to ask a child, gently, how things are going?", options: ["Bedwetting, withdrawal or a drop in concentration", "A good school report", "Being invited to a party"], answer: 0 }
  ] },
  { cert: true },
  { h: "Tell us what you thought" },
  "Your feedback shapes the next version. It takes two minutes.",
  { links: [["Email your feedback to Onesimus", "mailto:info@onesimus.org.au?subject=Practitioner%27s%20Training%20feedback&body=1.%20How%20would%20you%20describe%20the%20course%20overall%3F%20(Excellent%20%2F%20Good%20%2F%20Fair%20%2F%20Poor)%0A%0A2.%20What%20was%20most%20useful%3F%0A%0A3.%20What%20should%20change%3F%0A%0A4.%20Will%20your%20agency%20do%20anything%20differently%20as%20a%20result%3F%0A%0A5.%20Your%20sector%20and%20role%3A%0A"]] },
  { flag: "The workshop's evaluation form (handout 09) is offered here as an email, because the site has no form handler. To decide: a proper feedback form, and whether Onesimus wants a record of who completes the course. Registration is now through a standing event on the Events page, and the name and organisation given there appear on the certificate. The certificate is still made in the practitioner's browser, and Onesimus is not told when someone finishes." }
] });
